tool.command:
echo '[BeeGees] Step 1/3: resolving samples CSV against the FASTQ collection' && python3 '${__tool_directory__}/build_samples_csv.py' --samples-csv '$samples_file' --output samples.csv --collection-names #for $el in $reads# '${el.element_identifier}' #end for# --collection-paths #for $el in $reads# '${el}' #end for# #if $reference_source.ref_mode == 'gene_fetch' and $reference_source.gene_fetch.input_type == 'taxid' --require-taxid #end if #if $reference_source.ref_mode == 'manual' --refs-csv '$reference_source.sequence_reference_file' --refs-output sequence_references.csv --ref-names #for $el in $reference_source.protein_references# '${el.element_identifier}' #end for# --ref-paths #for $el in $reference_source.protein_references# '${el}' #end for# #end if || { echo '[BeeGees] FAILED at step 1/3 (build_samples_csv.py): check the samples CSV, references CSV and collection element names' >&2; exit 1; };
echo '[BeeGees] Step 2/3: building config.yaml' && #if $taxval.blast_db_source.source == 'history' ## tv_local_blast.py only runs makeblastdb for .fasta/.fa/.fas, and writes the index next to the file mkdir -p blast_db && ln -sf '$taxval.blast_db_source.blast_db_file' blast_db/blast_db.fasta && #end if python3 '${__tool_directory__}/build_config_yaml.py' --output config.yaml --ref-mode '$reference_source.ref_mode' #if $reference_source.ref_mode == 'manual' --sequence-reference-file sequence_references.csv #else --gf-email '$reference_source.gene_fetch.email' --gf-api-key '$reference_source.gene_fetch.api_key' --gf-gene '$reference_source.gene_fetch.gene' --gf-type '$reference_source.gene_fetch.fetch_type' --gf-minimum-length '$reference_source.gene_fetch.minimum_length' --gf-input-type '$reference_source.gene_fetch.input_type' #if $reference_source.gene_fetch.genbank --gf-genbank #end if #end if --fastp-adapter-r1 '$fastp.adapter_r1' --fastp-adapter-r2 '$fastp.adapter_r2' --fastp-extra-args '$fastp.extra_fastp_args' #if $downsampling.enabled == 'true' --downsampling-enabled --downsampling-max-reads '$downsampling.max_reads' #end if --br-r #for $v in $barcode_recovery.r_values# '$v' #end for# --br-s #for $v in $barcode_recovery.s_values# '$v' #end for# --br-n '$barcode_recovery.n' --br-C '$barcode_recovery.C' --br-t '$barcode_recovery.t' --fc-consensus-threshold '$fasta_cleaner.consensus_threshold' --fc-human-threshold '$fasta_cleaner.human_threshold' --fc-at-difference '$fasta_cleaner.at_difference' --fc-at-mode '$fasta_cleaner.at_mode' --fc-outlier-percentile '$fasta_cleaner.outlier_percentile' #if $fasta_cleaner.reference_filter.use_ref_filter == 'true' --fc-reference-dir '$fasta_cleaner.reference_filter.reference_dir' --fc-reference-filter-mode '$fasta_cleaner.reference_filter.reference_filter_mode' #end if --sv-target '$structural_validation.target' #if $structural_validation.verbose --sv-verbose #end if #if $taxval.blast_db_source.source == 'data_table' --tv-blast-db '$taxval.blast_db_source.blast_db.fields.path' #else --tv-blast-db blast_db/blast_db.fasta #end if #if $taxval.taxonomy_source.source == 'data_table' --tv-db-taxonomy '$taxval.taxonomy_source.db_taxonomy.fields.path' #else --tv-db-taxonomy '$taxval.taxonomy_source.db_taxonomy_file' #end if --tv-taxval-rank '$taxval.taxval_rank' #if $taxval.verbose --tv-verbose #end if --tv-min-pident '$taxval.min_pident' --tv-min-length '$taxval.min_length' || { echo '[BeeGees] FAILED at step 2/3 (build_config_yaml.py): check the tool form parameters' >&2; exit 1; };
echo '[BeeGees] Step 3/3: running the BeeGees Snakemake pipeline' && beegees run --config config.yaml --profile local #if $log_file --log-file '$log_out' #end if || { echo '[BeeGees] FAILED at step 3/3 (beegees run): see the Snakemake output above for the failing rule' >&2; exit 1; }
